function wrap(title, bodyHtml) {
  return `<html><head><meta charset="utf-8"></head><body style="margin:0; padding:0; background-color:#FAF6EF;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#FAF6EF;">
<tr><td align="center" style="padding: 40px 16px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px; background-color:#ffffff; border-radius:8px; overflow:hidden; border:1px solid #E3D9C6;">
<tr><td style="background-color:#241F1A; padding:28px 32px;">
<span style="font-family: Georgia, &quot;Times New Roman&quot;, serif; font-size:22px; color:#FAF6EF; font-weight:bold;">WorkflowIQ<span style="color:#E2934F;">.</span></span>
</td></tr>
<tr><td style="padding:36px 32px 8px;">
<h1 style="margin:0; font-family: Georgia, &quot;Times New Roman&quot;, serif; font-size:22px; font-weight:600; color:#241F1A;">${title}</h1>
</td></tr>
<tr><td style="padding:16px 32px 32px; font-family: Arial, Helvetica, sans-serif; font-size:15px; line-height:1.6; color:#5C5348;">
${bodyHtml}
</td></tr>
<tr><td style="padding:8px 32px 32px; font-family: Arial, Helvetica, sans-serif; font-size:12px; color:#9B9184; border-top:1px solid #E3D9C6;">
<p style="margin:20px 0 0;">WorkflowIQ by DadaAI</p>
</td></tr>
</table>
</td></tr>
</table>
</body></html>`;
}

function field(label, value) {
  return `<p style="margin:0 0 4px; font-size:12px; letter-spacing:0.06em; text-transform:uppercase; color:#C1602A; font-weight:bold;">${label}</p><p style="margin:0 0 16px; font-size:15px; color:#241F1A; font-weight:600;">${value}</p>`;
}

function button(url, label) {
  return `<table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background-color:#C1602A; border-radius:4px;"><a href="${url}" style="display:inline-block; padding:12px 28px; font-family: Arial, Helvetica, sans-serif; font-size:14px; font-weight:600; color:#FAF6EF; text-decoration:none;">${label}</a></td></tr></table>`;
}

function esc(v) {
  return String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}


const body = $('1. Webhook Trigger').item.json.body;
const productName = esc(body.product_name);
const companyName = esc(body.company_name || 'Not provided');
const buyerEmail = esc(body.buyer_email);
const paymentId = esc(body.payment_id);
const toolUrl = 'https://dada-wiq.167.233.94.171.nip.io';
// n8n Code nodes on this instance block $env access - confirmed via a
// real execution error, not assumed. This value is intentionally
// hardcoded rather than read from env. If STREAMLIT_APP_PASSWORD ever
// changes (see infra/.env), this line must be updated to match.
const toolPassword = '785q1JTVLQsSrJYMBKPP';

const content = `<p style="margin:0 0 20px;">A new WorkflowIQ order needs to be run.</p>` +
  field('Product', productName) +
  field('Company', companyName) +
  field('Buyer email', buyerEmail) +
  field('Payment ID', paymentId) +
  `<div style="margin:20px 0;">` + button(toolUrl, 'Open WorkflowIQ tool') + `</div>` +
  `<p style="margin:16px 0 4px; font-size:12px; letter-spacing:0.06em; text-transform:uppercase; color:#C1602A; font-weight:bold;">Tool password</p>` +
  `<p style="margin:0 0 16px; font-size:15px; color:#241F1A; font-weight:600; font-family: 'Courier New', monospace;">${toolPassword}</p>` +
  `<p style="margin:16px 0 0; font-size:14px; color:#9B9184;">Run the analysis in the tool, then it will automatically email the customer their report once marked complete.</p>`;

return [{ json: {
  subject: 'New WorkflowIQ order: ' + productName,
  html: wrap('New WorkflowIQ order', content)
} }];

